INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-001', '01', 'Magenta Plum Printed Three Piece', 'ম্যাজেন্টা ও প্লাম প্রিন্টেড থ্রি-পিস', 'magenta-plum-printed-three-piece', 2350, 'suggested', 'ম্যাজেন্টা ও প্লামের আকর্ষণীয় বৈপরীত্যে সাজানো এই থ্রি-পিসে আছে সাদা-গোলাপি ফুল, পেইসলি মোটিফ ও ডেকোরেটিভ বর্ডার। উজ্জ্বল ফুশিয়া সলিড কাপড় এবং ট্যাসেলসহ প্রিন্টেড ওড়না পুরো সেটে যোগ করে প্রাণবন্ত ফিনিশ।', 'প্লাম বেসে ফ্লোরাল-পেইসলি প্রিন্ট ও বর্ডার', 'উজ্জ্বল ফুশিয়া/পিংক সলিড কাপড়', 'ম্যাজেন্টা-প্লাম প্রিন্ট ও ট্যাসেল', 'Artisanal Handcraft', 'আলাদা হাতার কাপড়সহ আনস্টিচড', '#8E3B66', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-002', '02', 'Emerald Teal Batik', 'এমেরাল্ড টিল বাটিক থ্রি-পিস', 'emerald-teal-batik', 2150, 'suggested', 'কালো ও আইভরি রঙের অ্যাবস্ট্রাক্ট বাটিক-অনুপ্রাণিত নকশায় একটি স্বতন্ত্র লুক। টিল-সবুজ টাই-ডাই ঘরানার ওড়নার রাস্ট বর্ডার এবং টেরাকোটা রঙের সলিড কাপড় যোগ করেছে সাহসী, মার্জিত কনট্রাস্ট।', 'কালো/চারকোল বেসে আইভরি ফ্লোরাল ও জ্যামিতিক প্রিন্ট', 'টেরাকোটা/রাস্ট সলিড কাপড়', 'টিল-সবুজ স্ট্রাইপ ও রাস্ট বর্ডার', 'Artisanal Handcraft', 'আনস্টিচড বাটিক সেট', '#1F6E63', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-003', '02', 'Dusty Mauve Floral Batik', 'ডাস্টি মভ ফ্লোরাল বাটিক থ্রি-পিস', 'dusty-mauve-floral-batik', 2050, 'suggested', 'ডাস্টি মভের কোমল রঙে অফ-হোয়াইট ফুল এবং বড় বৃত্তাকার বাটিক মোটিফের পরিমিত সৌন্দর্য। একই টোনের সলিড কাপড় ও সূক্ষ্ম ফ্লোরাল প্রিন্টের ট্যাসেলযুক্ত ওড়নায় তৈরি হয়েছে সহজ, রুচিশীল থ্রি-পিস কম্বিনেশন।', 'ডাস্টি মভে সাদা ফুল ও গোলাকার বাটিক মোটিফ', 'ম্যাচিং ডাস্টি মভ সলিড কাপড়', 'মভ ফ্লোরাল প্রিন্ট, সূক্ষ্ম টেক্সচার ও ট্যাসেল', 'Artisanal Handcraft', 'আনস্টিচড বাটিক সেট', '#A87C8F', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-004', '03', 'Forest Elegance', 'ফরেস্ট এলিগ্যান্স', 'forest-elegance', 1850, 'suggested', 'মাটির রঙের উষ্ণতা ও ফরেস্ট গ্রিনের গভীরতা মিলেছে বোটানিক্যাল বাটিক-অনুপ্রাণিত নকশায়। ড্রেস ম্যাটেরিয়ালের সঙ্গে বাদামি সলিড কাপড় ও সবুজ গ্রেডিয়েন্ট ওড়নার পাতার ছাপ এবং ট্যাসেল পুরো লুকে আনে প্রাকৃতিক আবহ।', 'আর্থি ব্রাউন ও ফরেস্ট গ্রিন বোটানিক্যাল প্রিন্ট', 'সলিড ব্রাউন কাপড়', 'সবুজ গ্রেডিয়েন্ট ওড়না, ক্রিম বোটানিক্যাল ছাপ', 'Artisanal Handcraft', 'ড্রেস ম্যাটেরিয়াল', '#3E5E3A', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-005', '03', 'Fuchsia Noir', 'ফুশিয়া নোয়ার', 'fuchsia-noir', 1700, 'suggested', 'তীক্ষ্ণ ফুশিয়া-পিংক ও চারকোলের ড্রামাটিক কনট্রাস্টে নজরকাড়া বাটিক থ্রি-পিস ম্যাটেরিয়াল। কামিজের ওপর গোলাপি ও সাদা ফুলেল ছাপ, সঙ্গে সলিড ফুশিয়া কাপড় এবং গাঢ় থেকে উজ্জ্বল রঙে পরিবর্তিত ওড়না।', 'চারকোল/কালো বেসে ফুশিয়া ও সাদা ফ্লোরাল প্রিন্ট', 'উজ্জ্বল ফুশিয়া সলিড কাপড়', 'ফুশিয়া-চারকোল গ্রেডিয়েন্ট ও ফুলের মোটিফ', 'Artisanal Handcraft', 'ড্রেস ম্যাটেরিয়াল', '#B0326E', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-006', '03', 'Mustard Noir', 'মাস্টার্ড নোয়ার', 'mustard-noir', 1650, 'suggested', 'উজ্জ্বল মাস্টার্ড ও গাঢ় চারকোলের দুই-টোন প্যালেটে ক্লাসিক বাটিক ঘরানার নকশা। ছোট বোটানিক্যাল রিপিট প্রিন্টের সঙ্গে সলিড হলুদ কাপড় ও গ্রেডিয়েন্ট ওড়না।', 'চারকোল বেসে মাস্টার্ড বোটানিক্যাল রিপিট', 'সলিড মাস্টার্ড হলুদ কাপড়', 'হলুদ-চারকোল গ্রেডিয়েন্ট ওড়না', 'Artisanal Handcraft', 'ড্রেস ম্যাটেরিয়াল', '#C0912F', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-007', '03', 'Burgundy Sunset', 'বারগান্ডি সানসেট', 'burgundy-sunset', 1750, 'suggested', 'বারগান্ডি ও সানসেট-মাস্টার্ডের উষ্ণ মেলবন্ধনে ব্যতিক্রমী টাই-ডাই অনুপ্রাণিত ড্রেস ম্যাটেরিয়াল। গোলাকার বাটিক স্ট্যাম্পের মতো মোটিফ ও রঙিন ওড়না।', 'গাঢ় বারগান্ডি বেসে মাস্টার্ড বৃত্তাকার মোটিফ', 'ম্যাচিং কাপড় (যাচাই সাপেক্ষ)', 'বারগান্ডি-মাস্টার্ড টাই-ডাই ওড়না', 'Artisanal Handcraft', 'ড্রেস ম্যাটেরিয়াল', '#7E2F3C', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn;
INSERT INTO public.products (sku, collection_id, title, title_bn, slug, price_bdt, price_confidence, description_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, accent_color, is_featured) VALUES ('CAT-008', '04', 'Navy Royal Bloom', 'নেভি রয়্যাল ব্লুম', 'navy-royal-bloom', 1750, 'suggested', 'গভীর নেভি ব্লু বেসে সাদা অলঙ্করণধর্মী কেন্দ্রীয় নকশা এবং উষ্ণ বর্ডারের ক্লাসিক কনট্রাস্ট। হলুদ ফুলেল ওড়না ও গাঢ় সলিড কাপড়ের আনস্টিচড থ্রি-পিস।', 'নেভিতে সাদা অর্নামেন্টাল প্যানেল ও বর্ডার', 'সলিড গাঢ় নেভি কাপড়', 'হলুদ ফুল ও গাঢ় বর্ডারযুক্ত ওড়না', 'Artisanal Handcraft', 'আনস্টিচড (Unstitched)', '#2C4470', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn;
